CREATE TABLE IF NOT EXISTS contract_change_cases(id TEXT PRIMARY KEY,contract_id TEXT NOT NULL,change_no TEXT NOT NULL,reason TEXT NOT NULL,responsibility TEXT,effective_date TEXT,status TEXT NOT NULL,before_amount TEXT NOT NULL,delta_amount TEXT NOT NULL,after_amount TEXT NOT NULL,before_snapshot_json TEXT NOT NULL,after_snapshot_json TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,approved_by TEXT,approved_at TEXT,applied_by TEXT,applied_at TEXT,row_version INTEGER NOT NULL DEFAULT 1,UNIQUE(contract_id,change_no));
CREATE TABLE IF NOT EXISTS contract_change_case_lines(id TEXT PRIMARY KEY,case_id TEXT NOT NULL,action TEXT NOT NULL,contract_item_id TEXT,source_budget_item_id TEXT,item_no TEXT,name TEXT,unit TEXT,quantity_delta TEXT NOT NULL,unit_price TEXT NOT NULL,amount_delta TEXT NOT NULL,sort_order INTEGER NOT NULL);
